def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]
    opp_def = sum(1 for a in op if a == 'D')
    my_def = sum(1 for a in me if a == 'D')
    last_me = me[-1]
    last_op = op[-1]

    def opp_def_last(k):
        return sum(1 for a in op[-k:] if a == 'D')

    def opp_coop_last(k):
        return sum(1 for a in op[-k:] if a == 'C')

    # Endgame: exploit cooperators hard, punish defectors, avoid pointless mutual D.
    if n >= 96:
        if opp_def == 0:
            return 'D'
        if opp_coop_last(10) >= 6:
            return 'D'
        if last_op == 'D':
            return 'D'
        return 'C'

    # Opening: cooperate to establish mutual cooperation, retaliate quickly.
    if n < 4:
        if last_op == 'D':
            return 'D'
        return 'C'

    # Strong short-window defection response.
    if opp_def_last(4) >= 3:
        return 'D'

    # Very cooperative opponent: cooperate tightly, with rare probes in midgame.
    if opp_def_last(10) <= 1:
        if n > 80:
            return 'C'
        if n > 30 and rng.random() < 0.04:
            return 'D'
        return 'C'

    # Mostly cooperative: cooperate, punish isolated defections briefly.
    if opp_def_last(10) <= 3:
        if last_op == 'D' and last_me == 'C':
            return 'D'
        if last_op == 'D' and last_me == 'D':
            return 'D' if rng.random() < 0.6 else 'C'
        if last_op == 'C':
            return 'C'
        return 'C'

    # Moderate defection rate: tit-for-tat with forgiveness.
    if opp_def_last(10) <= 5:
        if last_op == 'D':
            if last_me == 'D':
                return 'D' if rng.random() < 0.75 else 'C'
            return 'D' if rng.random() < 0.5 else 'C'
        if last_op == 'C':
            if rng.random() < 0.08:
                return 'D'
            return 'C'

    # High defection: punish hard, but occasionally test cooperation to recover.
    if opp_def_last(10) >= 8:
        if rng.random() < 0.06:
            return 'C'
        return 'D'

    # Broad defector: defect mostly, test occasionally.
    if opp_def * 2 > n:
        if rng.random() < 0.12:
            return 'C'
        return 'D'

    # Otherwise: reciprocate last action with forgiveness.
    if last_op == 'D':
        if opp_coop_last(5) >= 3:
            return 'C' if rng.random() < 0.35 else 'D'
        return 'D'
    return 'C'
